sailNumber":"1916","sailNumberIlca4":null,"nationality":"AUS","gender":"M","club":"Rsys","birthYear":null},{"id":"f9a37376-1672-5dfb-98a2-a7e5006893d1","name":"Charlie Mclaren","handle":"opti-aus-charlie-mclaren-1398","sailNumber":"1398","sailNumberIlca4":null,"nationality":"AUS","gender":"M","club":"SSCBC","birthYear":null},{"id":"fcc78b34-55f5-597d-98c0-c5bfd31e81ef","name":"Alex Walker","handle":"opti-aus-alex-walker-1685","sailNumber":"1685","sailNumberIlca4":null,"nationality":"AUS","gender":null,"club":"Royal Queensland Yacht Squadron","birthYear":null},{"id":"ff95dfaa-563f-49ec-9d09-7cdd09128577","name":"Jungwon Park","handle":"jungwon-park-anz26-ff95df","sailNumber":"4710","sailNumberIlca4":null,"nationality":"NZL","gender":"M","club":"Kohimarama Yacht Club","birthYear":null}],"newProfiles":[{"id":"ccac2277-978e-558c-a8c8-9c4727861f72","name":"Kai TELFORD","handle":"kai-telford-aus25-ccac22","sailNumber":"1798","sailNumberIlca4":null,"club":"WSC","gender":null,"nationality":null},{"id":"741b1320-998a-55fd-92f7-4fa41c74e525","name":"Ellia JONES","handle":"ellia-jones-aus25-741b13","sailNumber":"346","sailNumberIlca4":null,"club":"LBSC","gender":"F","nationality":null},{"id":"51b53b7d-6169-5a41-96d5-6d39d5638d32","name":"Lucas YUNING","handle":"lucas-yuning-aus25-51b53b","sailNumber":"1674","sailNumberIlca4":null,"club":"HHSC","gender":null,"nationality":null},{"id":"3ec1d829-56ea-591b-aa4b-0032547e95ee","name":"Lucas SHOU","handle":"lucas-shou-aus25-3ec1d8","sailNumber":"1089","sailNumberIlca4":null,"club":"WSC","gender":null,"nationality":null},{"id":"fecf8f46-3610-5eed-8fe6-a917cc6d0660","name":"Angus KEDDIE","handle":"angus-keddie-aus25-fecf8f","sailNumber":"1796","sailNumberIlca4":null,"club":"RQYS","gender":null,"nationality":null},{"id":"da44e466-7859-5a6f-820e-d5d1e8f4314e","name":"Lawson BARNES","handle":"lawson-barnes-aus25-da44e4","sailNumber":"1427","sailNumberIlca4":null,"club":"RQYS","gender":null,"nationality":null},{"id":"f1dd8024-a9d1-54e3-a22